mapper.select:
SELECT
NVL((SELECT COUNT(1)
     FROM TR_SVC_QUALITY_CMPL c
     LEFT JOIN TR_DEPT_DICT d ON c.dept_code = d.dept_code
     WHERE c.stat_date BETWEEN #{startDate} AND #{endDate}

         AND c.dept_code = #{deptCode}


         AND d.dept_name LIKE '%' || #{deptName} || '%'

), 0) AS complaintCount,
NVL((SELECT COUNT(1)
     FROM TR_SVC_QUALITY_PRZ p
     LEFT JOIN TR_DEPT_DICT d ON p.dept_code = d.dept_code
     WHERE p.stat_date BETWEEN #{startDate} AND #{endDate}

         AND p.dept_code = #{deptCode}


         AND d.dept_name LIKE '%' || #{deptName} || '%'

), 0) AS praiseCount
FROM DUAL

SELECT c.id, c.stat_date AS statDate, c.complaint_time AS complaintTime, c.dept_code AS deptCode, NVL(d.dept_name, c.dept_name) AS deptName, c.person_name AS personName, c.position, c.category, c.result, c.remark FROM TR_SVC_QUALITY_CMPL c LEFT JOIN TR_DEPT_DICT d ON c.dept_code = d.dept_code WHERE c.stat_date BETWEEN #{startDate} AND #{endDate}
AND c.dept_code = #{deptCode}
AND d.dept_name LIKE '%' || #{deptName} || '%'
ORDER BY c.complaint_time DESC

SELECT p.id, p.stat_date AS statDate, p.praise_time AS praiseTime, p.dept_code AS deptCode, NVL(d.dept_name, p.dept_name) AS deptName, p.person_name AS personName, p.position, p.method, p.feedback, p.remark FROM TR_SVC_QUALITY_PRZ p LEFT JOIN TR_DEPT_DICT d ON p.dept_code = d.dept_code WHERE p.stat_date BETWEEN #{startDate} AND #{endDate}
AND p.dept_code = #{deptCode}
AND d.dept_name LIKE '%' || #{deptName} || '%'
ORDER BY p.praise_time DESC
